fade_transicao_pagina.js:
(function(){
  document.addEventListener('DOMContentLoaded', function(){
    document.body.classList.add('sl-loaded');
  });
  document.addEventListener('click', function(e){
    var link = e.target.closest('a[href]');
    if(!link) return;
    var href = link.getAttribute('href');
    if(!href || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('tel:')) return;
    if(link.target === '_blank') return;
    try{
      var url = new URL(href, location.href);
      if(url.hostname !== location.hostname) return;
    }catch(err){ return; }
    e.preventDefault();
    document.body.classList.remove('sl-loaded');
    setTimeout(function(){ location.href = href; }, 300);
  });
})();

reveal_on_scroll.js:
(function(){
  if(!('IntersectionObserver' in window)) {
    document.querySelectorAll('.sl-reveal').forEach(function(el){ el.classList.add('sl-visible'); });
    return;
  }
  var observer = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var delay = parseInt(entry.target.dataset.delay || 0, 10);
        setTimeout(function(){ entry.target.classList.add('sl-visible'); }, delay);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });
  document.querySelectorAll('.sl-reveal').forEach(function(el){ observer.observe(el); });
})();

barra_progresso_leitura.js:
(function(){
  var bar = document.getElementById('sl-read-progress');
  if(!bar) return;
  window.addEventListener('scroll', function(){
    var scrollTop = window.scrollY || document.documentElement.scrollTop;
    var docHeight = document.documentElement.scrollHeight - window.innerHeight;
    if(docHeight <= 0){ bar.style.width = '0'; return; }
    var pct = Math.min(100, (scrollTop / docHeight) * 100);
    bar.style.width = pct + '%';
  }, { passive: true });
})();

animacao_contador_scroll.js:
(function(){
  if(!('IntersectionObserver' in window)) return;
  function animateCounter(el, target){
    var start = 0;
    var duration = 1500;
    var step = target / (duration / 16);
    var timer = setInterval(function(){
      start = Math.min(start + step, target);
      el.textContent = Math.floor(start).toLocaleString('pt-BR');
      if(start >= target) clearInterval(timer);
    }, 16);
  }
  var observer = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var numEl = entry.target.querySelector('.sl-count-num');
        var target = parseInt(entry.target.dataset.target, 10);
        if(numEl && !isNaN(target)) animateCounter(numEl, target);
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });
  document.querySelectorAll('.sl-counter-item').forEach(function(el){ observer.observe(el); });
})();
